package com.shopsphere;import jakarta.validation.Valid;import java.math.BigDecimal;import java.util.UUID;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/products") public class ProductController{private final ProductService service;ProductController(ProductService s){service=s;}@GetMapping("/admin") public ProductDtos.Page<Product> admin(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.admin(page,size);}@GetMapping public ProductDtos.Page<Product> list(@RequestParam(required=false)String category,@RequestParam(required=false)String brand,@RequestParam(required=false)BigDecimal minPrice,@RequestParam(required=false)BigDecimal maxPrice,@RequestParam(required=false)Double rating,@RequestParam(defaultValue="newest")String sort,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.search(null,category,brand,minPrice,maxPrice,rating,sort,Math.max(0,page),Math.max(1,Math.min(size,100)));}@GetMapping("/search")public ProductDtos.Page<Product> search(@RequestParam String q,@RequestParam(required=false)String category,@RequestParam(required=false)String brand,@RequestParam(required=false)BigDecimal minPrice,@RequestParam(required=false)BigDecimal maxPrice,@RequestParam(required=false)Double rating,@RequestParam(defaultValue="relevance")String sort,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.search(q.trim(),category,brand,minPrice,maxPrice,rating,sort,Math.max(0,page),Math.max(1,Math.min(size,100)));}@GetMapping("/{id}")public Product get(@PathVariable UUID id){return service.get(id);}@GetMapping("/slug/{slug}")public Product slug(@PathVariable String slug){return service.slug(slug);}@PostMapping @ResponseStatus(HttpStatus.CREATED)public Product create(@Valid@RequestBody ProductDtos.Request r){return service.create(r);}@PutMapping("/{id}")public Product update(@PathVariable UUID id,@Valid@RequestBody ProductDtos.Request r){return service.update(id,r);}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable UUID id){service.delete(id);}}
